sys_script_client.script:
function onSubmit() {
   if (g_user.hasRole('x_58872_needit.security_officer')) {
		return true;
   }

   var confidential = g_form.getValue('x_58872_needit_confidential');
   var assignedTo = g_form.getValue('assigned_to');

   if (confidential == 'true' && assignedTo == '') {
		g_form.addErrorMessage('You have set incident to Confidential but you are not specified in Assigned To. If you save your incident then it will become invisible for you.');
		return false;
   }
   return true;
}
